public static int squarePermutations(int[] A) {
    int len = A.length;
    int count = 0;
    boolean[] used = new boolean[len];

    public void dfs(List<Integer> perm, int idx) {
        if (idx == len) {
            count++;
            return;
        }

        for (int i = 0; i < len; i++) {
            if (used[i] || !isPerfectSquare(perm.get(idx) + A[i])) {
                continue;
            }
            used[i] = true;
            perm.add(A[i]);
            dfs(perm, idx + 1);
            perm.remove(perm.size() - 1);
            used[i] = false;
        }
    }

    public boolean isPerfectSquare(int n) {
        int root = (int) Math.sqrt(n);
        return root * root == n;
    }

    public int squarePermutations(int[] A) {
        Arrays.sort(A);
        dfs(new ArrayList<>(), 0);
        return count;
    }
}

